// Regenerates src/data/dictionaryEn.js from the committed Malay→English DICTIONARY
// by reversing + cleaning it (src/lib/reverseDictionary.js). Run when dictionary.js
// changes: `npm run build:en-dict`. Prints the yield (spec Q-SEED) so the drop
// counts are visible, never silent. The generated file is committed + lazy-imported
// (it must NOT land in the eager bundle — spec N4).
import { writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import path from 'node:path'
import { buildEnDictionary } from '../src/lib/reverseDictionary.js'
import DICTIONARY from '../src/data/dictionary.js'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const outPath = path.join(__dirname, '..', 'src', 'data', 'dictionaryEn.js')

const { entries, stats } = buildEnDictionary(DICTIONARY)
const sorted = Object.fromEntries(Object.entries(entries).sort(([a], [b]) => a.localeCompare(b)))

const header =
  `// English→Malay study seed — GENERATED by scripts/build-en-dictionary.mjs (do not hand-edit).\n` +
  `// ${stats.kept} English headwords from ${stats.source} Malay entries · dropped: ` +
  `${stats.droppedMultiWord} multi-word, ${stats.droppedSlash} slash-defs, ${stats.droppedEmpty} empty ` +
  `· ${stats.collisionsMerged} collisions merged. STARTER set for IGCSE 0510 (English as a Second\n` +
  `// Language) — IGCSE-Malay vocab seen from the other side, not a curated English frequency list.\n` +
  `// See docs/superpowers/specs/2026-06-14-true-english-study-mode-design.md (Fork E).\n`
const body = `const DICTIONARY_EN = ${JSON.stringify(sorted, null, 2)};\n\nexport default DICTIONARY_EN;\n`

await writeFile(outPath, header + body)
console.table(stats)
console.log(`wrote ${path.relative(path.join(__dirname, '..'), outPath)} (${stats.kept} entries)`)
